function F({registerIndicator:b,sourceValues:N,percentileNearestRank:u,nulls:d}){const h=(c,n)=>{const r=c.length,m=new Array(r).fill(NaN),a=2/(n+1);let o=0,l=0,t=NaN;for(let i=0;i<r;i++){const s=c[i];if(Number.isFinite(s)){if(!Number.isFinite(t)){o+=s,l+=1,l>=n&&(t=o/n,m[i]=t);continue}t=s*a+t*(1-a),m[i]=t}}return m};b({id:"oa-hampel-filter",name:"Hampel Filter (HF)",category:"Moving Averages",placement:"onchart",inputs:[{key:"length",type:"number",label:"Length",default:14,min:1,max:5e3,step:1},{key:"scalingFactor",type:"number",label:"Scaling Factor",default:3,min:.1,max:100,step:.1,tooltip:"How many median absolute deviations a sample may sit from the median before it is replaced by it."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"hf",type:"line",title:"HF",style:{color:"#6d1e7f",lineWidth:2}}],calc(c,n){const r=Math.max(1,Math.floor(Number(n.length)||14)),m=Math.max(.1,Number(n.scalingFactor)||3),a=N(c,n.source||"close"),o=c.length,l=u(a,r,50),t=new Array(o).fill(NaN);for(let e=0;e<o;e++)!Number.isFinite(a[e])||!Number.isFinite(l[e])||(t[e]=Math.abs(a[e]-l[e]));const i=u(t,r,50),s=new Array(o).fill(NaN);for(let e=0;e<o;e++){if(!Number.isFinite(l[e]))continue;const f=Number.isFinite(t[e])?t[e]:NaN,y=Number.isFinite(f)&&Number.isFinite(i[e])&&f<=m*i[e];s[e]=y?a[e]:l[e]}return{hf:d(h(s,r))}}})}export{F as default};
